inline constexpr size_t Count = sizeof(Ids) / sizeof(Ids[0]);
inline bool Is(uint32_t item_id)
{
	size_t lo = 0, hi = Count;
	while (lo < hi) {
		const size_t mid = (lo + hi) / 2;
		if (Ids[mid] < item_id) { lo = mid + 1; }
		else if (Ids[mid] > item_id) { hi = mid; }
		else { return true; }
	}
	return false;
}
